function centsToDisplay(value: number) {
  return value > 0 ? (value / 100).toFixed(2) : "";
}

function displayMediaBytes(value: number) {
  if (value < 1024 * 1024) return `${Math.max(0, Math.round(value / 1024))} Ko`;
  return `${(Math.max(0, value) / (1024 * 1024)).toFixed(value >= 100 * 1024 * 1024 ? 0 : 1)} Mo`;
}

function displayToCents(value: string) {
  const normalized = value.trim().replace(",", ".");
  if (!normalized) return 0;
  const parsed = Number(normalized);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.round(parsed * 100) : 0;
}

function signedDisplayToCents(value: string): number | null {
  const normalized = value.trim().replace(",", ".");
  if (!normalized) return 0;
  const parsed = Number(normalized);
  if (!Number.isFinite(parsed)) return null;
  const cents = Math.round(parsed * 100);
  return cents >= -10_000_000 && cents <= 10_000_000 ? cents : null;
}

