function slugify(value: string) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 220);
}

function parseProductVariantOptions(raw: unknown): Array<{ name: string; values: string[] }> {
  try {
    const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
    if (!Array.isArray(parsed)) return [];
    return parsed.flatMap(item => {
      const name = typeof item?.name === "string" ? item.name.trim().slice(0, 60) : "";
      const values: string[] = Array.isArray(item?.values) ? Array.from(new Set(item.values.filter((value: unknown): value is string => typeof value === "string").map((value: string) => value.trim()).filter(Boolean) as string[])).slice(0, 30) : [];
      return name && values.length ? [{ name, values }] : [];
    }).slice(0, 4);
  } catch {
    return [];
  }
}

function fileToDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

